const FAST = 12, SLOW = 26, SIG = 9, PERIOD = 1800;
const EPS = 1e-9;
const FORCE_TEST_OUTPUT = false; // 設為 true 可輸出全部幣種檢查對應

function ema(v, p) {
  const k = 2 / (p + 1);
  const r = Array(v.length).fill(null);
  if (v.length < p) return r;
  let s = 0;
  for (let i = 0; i < p; i++) s += v[i];
  r[p - 1] = s / p;
  let prev = r[p - 1];
  for (let i = p; i < v.length; i++) {
    prev = v[i] * k + prev * (1 - k);
    r[i] = prev;
  }
  return r;
}

function macd(closes) {
  const ef = ema(closes, FAST);
  const es = ema(closes, SLOW);
  const n = closes.length;
  const dif = Array(n).fill(null);
  for (let i = 0; i < n; i++) {
    if (ef[i] !== null && es[i] !== null) dif[i] = ef[i] - es[i];
  }

  const svals = dif.filter(x => x !== null);
  const sig = Array(n).fill(null);
  if (svals.length >= SIG) {
    const esig = ema(svals, SIG);
    let st = dif.findIndex(x => x !== null);
    for (let j = 0; j < esig.length; j++) {
      if (esig[j] !== null) sig[st + j] = esig[j];
    }
  }

  const hist = Array(n).fill(null);
  for (let i = 0; i < n; i++) {
    if (dif[i] !== null && sig[i] !== null) hist[i] = dif[i] - sig[i];
  }
  return { dif, sig, hist };
}

// 1. 動態讀取設定節點的市場清單與數量
let marketList = ['btctwd', 'ethtwd', 'dogetwd', 'shibtwd'];
try {
  // 自動適配可能叫 '設定市場清單' 或 'Code in JavaScript'
  const setNode = $('設定市場清單').all().length > 0 ? $('設定市場清單') : $('Code in JavaScript');
  marketList = setNode.all().map(i => String(i.json.market || '').toLowerCase());
} catch (e) {}

const allItems = $input.all();
const totalItems = allItems.length;
const chunkSize = Math.floor(totalItems / marketList.length);
const out = [];

console.log(`=== 開始驗證市場對應 (總筆數: ${totalItems}, 每組筆數: ${chunkSize}) ===`);

for (let mIdx = 0; mIdx < marketList.length; mIdx++) {
  const market = marketList[mIdx].toUpperCase();
  const startIdx = mIdx * chunkSize;
  const endIdx = (mIdx + 1) * chunkSize;
  const marketChunk = allItems.slice(startIdx, endIdx);

  const klines = [];
  for (const item of marketChunk) {
    const raw = item.json;
    if (Array.isArray(raw)) {
      klines.push(raw);
    } else if (typeof raw === 'object' && raw !== null) {
      const row = Object.values(raw);
      if (row.length >= 6) klines.push(row);
    }
  }

  if (klines.length < SLOW + SIG) {
    console.warn(`[${market}] K線數量不足 (${klines.length})`);
    continue;
  }

  // 時間升序排列
  klines.sort((a, b) => Number(a[0]) - Number(b[0]));

// 修改為：直接取 API 回傳的最新一根完整收線 K 線
  const lastClosedIdx = klines.length - 1;
  const prevClosedIdx = lastClosedIdx - 1;
  if (prevClosedIdx < 0) continue;

  const closes = klines.map(k => Number(k[4]));
  const latestPrice = closes[lastClosedIdx];
  const { dif, sig, hist } = macd(closes);

  const i = lastClosedIdx;
  const p = prevClosedIdx;

  if (hist[i] === null || hist[p] === null) continue;

  const isDeathCross = (hist[p] >= -EPS) && (hist[i] < -EPS);

  // 印出各幣種當前收盤價以利人工肉眼核對
  console.log(`[驗證通過] 幣種: ${market} | 索引範圍: ${startIdx}~${endIdx-1} | 最新收盤價: ${latestPrice} TWD | 死叉: ${isDeathCross}`);

  if (isDeathCross || FORCE_TEST_OUTPUT) {
    out.push({
      json: {
        market: market,
        close: latestPrice,
        candle_ts: Number(klines[i][0]),
        dif: Number(dif[i].toFixed(4)),
        signal: Number(sig[i].toFixed(4)),
        hist: Number(hist[i].toFixed(4)),
        isDeathCross: isDeathCross,
        audit_info: {
          data_count: klines.length,
          item_range: `${startIdx} - ${endIdx - 1}`
        }
      }
    });
  }
}

return out;

